---FillVo
---@param jsonData table
function BeginnerDojo:Fill(jsonData)
	jsonData = checkTable(jsonData)
	for key, value in pairs(jsonData) do
		--只更新自己关心的数据
		if isSet(jsonData, key) and table.haskey(self, key) then
			self[key] = value
		end
	end
	
	if isSet(self,"mall") then
		for i, v in pairs(self.mall) do
			self:ConvertPrices(v)
		end
	end
	
	local curTime = GameUtils.GetServerTime() or os.time()
	if isSet(self,"dailyRefreshTime") then
		self.dailyRefreshTime = self.dailyRefreshTime + curTime
	end
	
	for i, v in pairs(timeKey) do
		if isSet(self,v) then
			self[v] = self[v] + curTime
		end
	end
end

function BeginnerDojo:IsNeedTimeDown()
	local curTime = GameUtils.GetServerTime() or os.time()
	for i, v in pairs(timeKey) do
		local time = self[v] - curTime
		if time > 0 then
			return true
		end
	end
	return false
end

---将prices转为需要的格式
function BeginnerDojo:ConvertPrices(data)
	if not data.prices then return end
	local prices = {}
	for k, v in pairs(checkTable(data.prices)) do
		local tmp = {}
		tmp.current = v.current
		tmp.original = v.original
		tmp.currency = tonumber(k)
		table.insert(prices, tmp)
	end
	data.prices = prices
end

