function BeginnerDojo:UpdateHistoryHurt(hurt)
	if checkNumber(hurt) > self.bossMaxDamage then
		self.bossMaxDamage = hurt
	end
end

function BeginnerDojo:GetDailyRefreshTime()
	return self.dailyRefreshTime
end

function BeginnerDojo:UpdateDrawState(id)
	if checkNumber(id) > 0 then
		for i, v in pairs(self.bossDamageRewards) do
			if v.id == id then
				v.hasDrawn = 1
				break
			end
		end
	else
		local historyMaxHurt = self:GetBossHurt()
		local allCanDrawButNotInListRewards = {}
		for _, v in ipairs(self.bossDamageRewards) do
			local rewardVo = CfUtils.GetCf(AutoIds.IdSetting8923, "BeginnerBossHurtVo", v.id)
			if historyMaxHurt >= checkNumber(rewardVo.upperLimit) and (not self:IsHaveDrawBossHurtReward(rewardVo.id)) then
				self:UpdateDrawState(v.id)
			end
		end
	end
end

function BeginnerDojo:IsHaveDrawBossHurtReward(id)
	for i, v in pairs(self.bossDamageRewards) do
		if checkNumber(v.id) == id and checkNumber(v.hasDrawn) == 1 then
			return true
		end
	end
	return false
end

